if ~exist('src800s','var')
    src800s = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align_sym3.sqw');
end
if ~exist('src800','var')
    src800 = sqw('e:\SHARE\Fe\Data\sqw\sqw2024\Fe_ei800_align.sqw');
end

w2_00 = cut(src800s,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; keep_figure; %[output:0ff0048b]

w2_00 = cut(src800,line_proj(),0.04,0.04,[-0.1,0.1],[95,105]);
plot(w2_00);lz 0 1; keep_figure; %[output:5d6be568]

other800HNranges = {[-0.1,0.1],[-0.1,0.1],[0,4,500]};

% recover masks not to draw them again
[cuts2fit800HN,mask_file]  = recover_selected_cuts('cuts2fit800HN','e:\SHARE\Fe\Data\analysis\06_fit_with_J0\sym4D_cutsAndFits');
% retrieve selected cuts used for further fitting
[HN_FFCutsFits,allJfitfile] = recover_selected_cuts('HN_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');


hc = hor_config;
ll = hc.log_level;
hc.log_level = -2;
%%
% H<==>0.5
% max FF  0.5,1.5 dir
lp110offH1H0 = line_proj([1,1,0],[-1,1,0],'offset',[0.5,1.5,0]);
w2e800dir110ofH1H0 = cut(src800s,lp110offH1H0,[-1,0.02,5],other800HNranges{:});
fh = plot(w2e800dir110ofH1H0);liny; lz 0 1; %[output:5666e7ce]
[w2e800dir110ofH1H0,cuts2fit800HN] = draw_masks_helper(fh, ...
    cuts2fit800HN,'Ei800mskffH1H0_dir110',4);
plot(w2e800dir110ofH1H0);lz 0 0.5;keep_figure; %[output:5666e7ce]

lp110off1HH0 = line_proj([1,1,0],[-1,1,0],'offset',[1.5,0.5,0]);
w2e800dir110of1HH0 = cut(src800s,lp110off1HH0,[-1,0.02,5],other800HNranges{:});
fh = plot(w2e800dir110of1HH0); lz 0 1; %[output:8129418a]
[w2e800dir110of1HH0,cuts2fit800HN] = draw_masks_helper(fh, ...
    cuts2fit800HN,'Ei800mskff1HH0_dir110',4);
plot(w2e800dir110of1HH0);lz 0 0.5;keep_figure; %[output:8129418a]

w2e800dir110of1HH0s = sqw_op_bin_pixels({w2e800dir110ofH1H0,w2e800dir110of1HH0}, ...
    @move_all_to_proj, ...
    {[lp110offH1H0,lp110off1HH0]}, ...
    lp110offH1H0,[-0.5,0.02,0.5],other800HNranges{:},'-combine');
plot(w2e800dir110of1HH0s);liny; lz 0 0.2;keep_figure; %[output:166f4d7d]
%%
w2e800dir110of1HH0f = cut(w2e800dir110of1HH0s,[0,0.02,0.5],[50,4,290]) %[output:970154cf]
plot(w2e800dir110of1HH0f);liny; lz 0 0.2;keep_figure; %[output:4f035336]
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei800_offH1H0HNmaxFF',w2e800dir110of1HH0f);

save(mask_file,'cuts2fit800HN');
%%
% min FF influence; offset <1.5,1.5,0>
lpM110off1H1H0 = line_proj([-1,1,0],[1,1,0],'offset',[1.5,1.5,0]);
w2e800dirM110of1H1H0 = cut(src800s,lpM110off1H1H0 ,[-1.5,0.02,1.5],other800HNranges{:});
fh = plot(w2e800dirM110of1H1H0); lz 0 0.5; %[output:734ebd9c]
[w2e800dirM110of1H1H0,cuts2fit800HN] = draw_masks_helper(fh, ...
    cuts2fit800HN,'Ei800mskffH1H0_dirM110',3);
plot(w2e800dirM110of1H1H0); lz 0 0.5;keep_figure; %[output:734ebd9c]

w2e800dirM110of1H1H0s = cut(w2e800dirM110of1H1H0,[0,0.01,1.5],[59,4,450], ...
    SymopReflection('normvec',[-1,1,0],'offset',[1.5,1.5,0]));
plot(w2e800dirM110of1H1H0s); lz 0 0.2;keep_figure; %[output:8c2413f0]

w2e800dir110of1H1H0f = cut(w2e800dirM110of1H1H0s,[0,0.01,0.5],[50,4,350]);
plot(w2e800dir110of1H1H0f); lz 0 0.2; keep_figure; %[output:944ee3ce]

w2e800dir110ofH2H0f = cut(w2e800dirM110of1H1H0s,line_proj([-1,1,0],[1,1,0],'offset',[0.5,2.5,0]), ...
    [-0.5,0.01,0.5],[],[],[50,4,410]);
plot(w2e800dir110ofH2H0f); lz 0 0.2; keep_figure; %[output:19095efd]
w2e800ss = smooth(w2e800dir110ofH2H0f);
plot(w2e800ss); lz 0 0.2; keep_figure; %[output:0798e1d0]
%%
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei800_off1H1H0HNminFF',w2e800dir110of1H1H0f);
HN_FFCutsFits = save_selected_cuts(HN_FFCutsFits,allJfitfile, ...
    'Ei800_offH2H0HNminFF',w2e800dir110ofH2H0f);

save(mask_file,'cuts2fit800HN');
